style.css:
/* Abril Fatface + Typewriter */

body {
  font-family: "Courier New", monospace !important;
}

h1, h2, h3, h4, h5, h6 {
  font-family: "Abril Fatface", Georgia, serif !important;
  font-weight: 400 !important;
}

p, span, li, label, a {
  font-family: "Courier New", monospace !important;
}

button, input, textarea, select {
  font-family: "Courier New", monospace !important;
}
